"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[26658],{99207:e=>{e.exports=JSON.parse('{"tag":{"label":"backend customization","permalink":"/tags/backend-customization","allTagsPath":"/tags","count":18,"items":[{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/backend-customization/controllers","title":"Controllers","description":"Controllers bundle actions that handle business logic for each route within Strapi\u2019s MVC pattern. This documentation demonstrates generating controllers, extending core ones with createCoreController, and delegating heavy logic to services.","permalink":"/cms/backend-customization/controllers"},{"id":"cms/backend-customization/examples/services-and-controllers","title":"Custom services and controllers","description":"Learn how to authenticate use custom services and controllers using our FoodAdvisor example","permalink":"/cms/backend-customization/examples/services-and-controllers"},{"id":"cms/customization","title":"Customization","description":"Learn more about Strapi 5 customization possibilities","permalink":"/cms/customization"},{"id":"cms/backend-customization/middlewares","title":"Middlewares","description":"Middlewares alter the request or response flow at application or API levels. This documentation distinguishes global versus route middlewares and illustrates custom implementations with generation patterns.","permalink":"/cms/backend-customization/middlewares"},{"id":"cms/backend-customization/models","title":"Models","description":"Strapi models (i.e. content-types, components, and dynamic zones) define a representation of the content structure.","permalink":"/cms/backend-customization/models"},{"id":"cms/backend-customization/policies","title":"Policies","description":"Strapi policies are functions that execute specific logic on each request before it reaches the controller. Policies can be customized according to your needs.","permalink":"/cms/backend-customization/policies"},{"id":"cms/backend-customization/requests-responses","title":"Requests and Responses","description":"Learn more about requests and responses for Strapi, the most popular headless CMS.","permalink":"/cms/backend-customization/requests-responses"},{"id":"cms/backend-customization/routes","title":"Routes","description":"Strapi routes handle requests to your content and are auto-generated for your content-types. Routes can be customized according to your needs.","permalink":"/cms/backend-customization/routes"},{"id":"cms/plugins-development/server-api","title":"Server API for plugins","description":"Overview of the Strapi Server API for plugins, with entry file, lifecycle hooks, routes, controllers, services, policies, middlewares, and configuration.","permalink":"/cms/plugins-development/server-api"},{"id":"cms/plugins-development/server-configuration","title":"Server configuration","description":"Define default plugin options, validate user-provided values, and read plugin configuration at runtime.","permalink":"/cms/plugins-development/server-configuration"},{"id":"cms/plugins-development/server-content-types","title":"Server content-types","description":"Declare and register content-types in a Strapi plugin and access them at runtime through the Document Service API.","permalink":"/cms/plugins-development/server-content-types"},{"id":"cms/plugins-development/server-controllers-services","title":"Server controllers & services","description":"Handle HTTP requests in plugin controllers and organize reusable business logic in plugin services.","permalink":"/cms/plugins-development/server-controllers-services"},{"id":"cms/plugins-development/server-getters-usage","title":"Server getters & usage","description":"Access and reuse plugin controllers, services, policies, and other server resources using top-level and global getters.","permalink":"/cms/plugins-development/server-getters-usage"},{"id":"cms/plugins-development/server-policies-middlewares","title":"Server policies & middlewares","description":"Guard plugin routes with policies and intercept requests with middlewares in the Strapi plugin Server API.","permalink":"/cms/plugins-development/server-policies-middlewares"},{"id":"cms/plugins-development/server-routes","title":"Server routes","description":"Expose plugin endpoints as Content API or admin routes, with full control over auth, policies, and route configuration.","permalink":"/cms/plugins-development/server-routes"},{"id":"cms/backend-customization/services","title":"Services","description":"Strapi services are a set of reusable functions, useful to simplify controllers logic.","permalink":"/cms/backend-customization/services"},{"id":"cms/backend-customization/webhooks","title":"Webhooks","description":"Strapi webhooks are user-defined HTTP callbacks used by an application to notify other applications that an event occurred.","permalink":"/cms/backend-customization/webhooks"}],"unlisted":false}}')}}]);